[
  {
    "statement": "Based on a comprehensive review of available evidence, only one study was found demonstrating effectiveness for reducing human-primate conflict in agricultural areas.",
    "citations": []
  },
  {
    "statement": "A controlled, replicated, before-and-after study in Indonesia found that using nets to keep primates out of fruit trees reduced crop-raiding by orangutans.",
    "citations": [
      "1442"
    ]
  },
  {
    "statement": "Other proposed methods for reducing human-primate conflict include installing mechanical barriers, using unpalatable buffer crops, and changing to less palatable crops.",
    "citations": [
      "1436",
      "1438",
      "1439"
    ]
  },
  {
    "statement": "Other proposed methods also include compensating farmers for losses, paying farmers for deterrent costs, and providing sacrificial crop rows.",
    "citations": [
      "1428",
      "1429",
      "1427"
    ]
  },
  {
    "statement": "All other proposed interventions for reducing human-primate conflict lack quantitative evidence for their effectiveness or cost-effectiveness.",
    "citations": []
  },
  {
    "statement": "Systematic searches found no studies that directly tested these other proposed actions.",
    "citations": []
  }
]

[
  {
    "statement": "Evidence from primate reintroduction programs shows considerable geographic variation in success rates across continents.",
    "citations": []
  },
  {
    "statement": "Studies of primate reintroduction in South America show mixed results with relatively low survival rates.",
    "citations": []
  },
  {
    "statement": "Most golden lion tamarins reintroduced in Brazil did not survive for over 1 to 7 years.",
    "citations": []
  },
  {
    "statement": "A controlled study in French Guiana found that more reintroduced squirrel monkeys died or were returned to captivity compared to wild-born squirrel monkeys.",
    "citations": []
  },
  {
    "statement": "Primate reintroduction programs in Africa generally show higher success rates.",
    "citations": []
  },
  {
    "statement": "Reintroduced primate populations increased over 16 years in Tanzania and over 25 years in Gambia.",
    "citations": []
  },
  {
    "statement": "Most chimpanzees involved in reintroduction programs across multiple African countries survived for 1 to 5 years.",
    "citations": []
  },
  {
    "statement": "Some reintroduction failures in Africa were documented, including a chimpanzee in Uganda that repeatedly returned to human settlements.",
    "citations": []
  },
  {
    "statement": "Primate reintroduction programs in Madagascar show variable outcomes.",
    "citations": []
  },
  {
    "statement": "One success in Madagascar involved all reintroduced lemurs surviving for over 30 months and showing a diet overlap with wild populations.",
    "citations": []
  },
  {
    "statement": "A significant failure in Madagascar involved most reintroduced black-and-white ruffed lemurs not surviving for over 5 years.",
    "citations": []
  },
  {
    "statement": "Primate reintroduction programs in Asia have shown mixed results with some notable failures.",
    "citations": []
  },
  {
    "statement": "A reintroduced population of orangutans in Malaysia showed a decline over 33 years.",
    "citations": []
  },
  {
    "statement": "Reintroduced gibbon populations in Thailand declined over a period of 3 years.",
    "citations": []
  },
  {
    "statement": "Most lorises reintroduced in Vietnam and Indonesia were assumed dead within one year.",
    "citations": []
  },
  {
    "statement": "Limited evidence from primate reintroduction in Central America shows positive outcomes.",
    "citations": []
  },
  {
    "statement": "Reintroduced primate populations in Belize showed increases over a period of 5 years.",
    "citations": []
  }
]

[
  {
    "statement": "No action documents were found that specifically address the impact of plastic pollution in waterways on primate populations that live near rivers.",
    "citations": []
  },
  {
    "statement": "Searches identified related actions such as establishing riparian buffers to reduce pollutants reaching rivers.",
    "citations": []
  },
  {
    "statement": "Searches identified related actions such as reducing garbage and solid waste to avoid primate injuries.",
    "citations": []
  },
  {
    "statement": "None of the identified actions provided evidence specifically about plastic pollution effects on primates in river ecosystems.",
    "citations": []
  }
]
